import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Разделить изображение — короткая работа: загрузите фото, выберите, как его разделить, проверьте линии разреза и скачайте части. Это руководство проведёт вас по каждому шагу по порядку, от первой загрузки до готовых плиток.</p>\n<p>Перед началом нужна всего одна вещь: изображение, которое вы хотите разделить. Большой источник высокого разрешения даёт лучшие плитки, потому что каждая плитка разрезается в полном исходном размере. Маленький источник даёт маленькие плитки, поэтому используйте самый большой файл, какой у вас есть.</p>\n<p><a href=\"/ru/razdelit-izobrazhenie/\">Разделитель изображений</a> выполняет работу в вашем браузере. Ничего не загружается на сервер, учётная запись не нужна, а плитки скачиваются бесплатно. Следуйте шагам ниже — и через несколько минут у вас будет разделённое изображение.</p>\n<h2 id=\"step-1-upload-your-image\">Шаг 1. Загрузите изображение</h2>\n<p>Откройте разделитель и перетащите изображение в зону загрузки или нажмите, чтобы выбрать файл на устройстве. Можно также вставить изображение прямо из буфера обмена клавишами Ctrl и V — это удобно для скриншотов, которые вы не сохраняли как файлы.</p>\n<p>Инструмент принимает файлы JPG, PNG, WebP, HEIC, GIF, BMP и SVG до 20 МБ. Большинство фото и скриншотов намного меньше этого лимита. HEIC-фото с iPhone загружается и разделяется, как любой другой файл.</p>\n<p>Как только изображение загрузится, автоматически создаётся начальный разрез 3 на 3. Вы сразу увидите сетку и пронумерованные линии разреза в предпросмотре, что даёт отправную точку для настройки.</p>\n<p>Если вы загрузили не тот файл, замените его, не теряя настроек. Инструмент позволяет поменять изображение, сохранив режим разреза и размер сетки, поэтому ошибка стоит секунд, а не перезапуска.</p>\n<h2 id=\"step-2-choose-a-split-mode\">Шаг 2. Выберите режим разреза</h2>\n<p>Выберите один из трёх режимов: «Сетка», «Горизонтальные полосы» или «Вертикальные полосы». Сетка делит изображение на строки и столбцы и подходит для сеток Instagram, пазлов и постеров. Выберите её, когда плитки будут сидеть рядом, чтобы восстановить картинку.</p>\n<p>Горизонтальные полосы разрезают изображение на сложенные строки. Выберите этот режим для длинных скриншотов, высоких инфографик и всего, что читается сверху вниз. Каждая полоса — широкое, короткое изображение, которое чисто печатается или публикуется само по себе.</p>\n<p>Вертикальные полосы разрезают изображение на соседние столбцы. Выберите этот режим для широких панорам и баннеров, где каждая полоса продолжает сцену вправо. Панорама, разрезанная на вертикальные полосы, работает как листаемая карусель.</p>\n<p>Если не уверены, какой режим подходит, начните с сетки. Это самый гибкий режим, и вы можете переключиться на режим полос в любое время, не теряя изображение. Предпросмотр обновляется при переключении, поэтому разница видна сразу.</p>\n<h2 id=\"step-3-set-rows-and-columns\">Шаг 3. Задайте строки и столбцы</h2>\n<p>В режиме сетки задайте число строк и столбцов. Три строки и три столбца дают классическую сетку Instagram из девяти плиток. Два на два даёт простой разрез на четыре плитки, а четыре на четыре — шестнадцать плиток для большего пазла.</p>\n<p>Подумайте о размере плитки, прежде чем выбирать. Фото 3000 пикселей, разрезанное 3 на 3, даёт плитки по 1000 пикселей, достаточно большие для публикации где угодно. То же фото, разрезанное 10 на 10, даёт плитки по 300 пикселей — маленькие, подходящие только для миниатюр или мозаик.</p>\n<p>В режимах полос задайте вместо этого число полос. Четыре горизонтальные полосы для длинного скриншота, три вертикальные полосы для панорамы и две полосы для простого разреза. Полосы делят изображение поровну, поэтому их число определяет размер каждой части.</p>\n<p>Свободно меняйте числа и следите за предпросмотром. Линии разреза двигаются при настройке, а число плиток обновляется. Экспериментировать ничего не стоит, потому что ничего не скачивается, пока вы сами не попросите.</p>\n<h2 id=\"step-4-use-a-preset\">Шаг 4. Используйте предустановку</h2>\n<p>Предустановки — это настройки в один клик для распространённых разрезов. Предустановка сетки Instagram 3 на 3 — та, что нужна большинству людей, а инструмент включает и другие для распространённых размеров сетки и числа полос. Нажмите предустановку — и строки и столбцы заполнятся автоматически.</p>\n<p>Предустановка — это отправная точка. После нажатия поправьте числа, если вашему изображению или плану нужна другая форма. Предустановка экономит ввод, а вы сохраняете полный контроль над итоговым разрезом.</p>\n<p>Используйте предустановки, когда разделяете изображения часто. Менеджер соцсетей, который каждую неделю строит сетку, может нажимать ту же предустановку каждый раз и получать плитки одинакового размера, что сохраняет сетку профиля последовательной от одного пазла к другому.</p>\n<p>Если ни одна предустановка не подходит вашей задаче, задайте строки и столбцы вручную. Сетка 4 на 5 для постера или полоса 1 на 6 для баннера — оба допустимые разрезы, а ручные настройки покрывают каждую комбинацию до 10 на 10.</p>\n<h2 id=\"step-5-inspect-the-cut-lines\">Шаг 5. Проверьте линии разреза</h2>\n<p>Посмотрите на предпросмотр и найдите пронумерованные линии разреза. Они показывают ровно, где начинается и заканчивается каждая плитка, а номера сообщают позицию каждой плитки в сетке, при чтении слева направо и сверху вниз.</p>\n<p>Проверьте, не проходит ли какая-либо линия разреза через лицо, строку текста или важную деталь. Лицо, разрезанное на две плитки, выглядит как ошибка, а текст, разрезанный пополам, нечитаем в обеих плитках. Если разрез лёг неудачно, измените сетку или переместите изображение.</p>\n<p>Для неквадратного источника проверьте формы плиток. Широкое фото, разрезанное 3 на 3, даёт широкие плитки, а не квадраты, и эти плитки могут не подойти квадратной сетке. Поправьте строки и столбцы или сначала обрежьте источник до квадрата, чтобы плитки получились нужной формы.</p>\n<p>Увеличьте предпросмотр, если изображение детальное. Линии разреза, которые при малом размере выглядят нормально, могут скрывать проблему в загруженной области фото. Несколько секунд проверки экономят скачивание и повторный разрез.</p>\n<h2 id=\"step-6-choose-the-tile-format\">Шаг 6. Выберите формат плиток</h2>\n<p>Выберите формат плиток. JPG подходит фото и даёт маленькие файлы, что нужно для постов в соцсетях и использования в интернете. PNG подходит графике, тексту и всему с прозрачностью, потому что он сохраняет каждый пиксель точно.</p>\n<p>Ползунок «Качество плиток» появляется для плиток JPG. Он управляет сжатием выходного JPG, поэтому более высокое значение сохраняет больше деталей, а более низкое даёт меньшие файлы. Плитки PNG без потерь и ползунка качества не имеют.</p>\n<p>Для прозрачных источников PNG выберите PNG как формат плиток. У JPG нет прозрачности, поэтому прозрачная плитка, экспортированная как JPG, получает сплошной фон. Прозрачность переживает только формат, который её поддерживает.</p>\n<p>Подбирайте формат под место назначения. Посты в соцсетях и печать хорошо работают с JPG, а спрайт-листы, иконки и дизайнерские материалы нуждаются в PNG. Когда сомневаетесь, экспортируйте PNG для графики и JPG для фотографий.</p>\n<h2 id=\"step-7-download-the-tiles\">Шаг 7. Скачайте плитки</h2>\n<p>Скачайте плитки как ZIP-архив, чтобы получить их все сразу. ZIP содержит каждую плитку как пронумерованный файл в порядке чтения от верхнего левого угла. Распакуйте его — и набор готов к использованию, а номера показывают, где принадлежит каждая плитка.</p>\n<p>Можно также скачивать плитки по одной, если нужны лишь несколько из них. Одна плитка для фото профиля или одна полоса для баннера не требует весь набор, а отдельное скачивание пропускает шаг распаковки.</p>\n<p>Проверьте размеры плиток после скачивания. Откройте одну плитку и убедитесь, что она того размера, который вы ожидали, особенно для печати или спрайт-листов, где важны точные пиксели. Быстрая проверка сейчас ловит неверную настройку сетки до того, как вы используете плитки.</p>\n<p>Держите ZIP-архив как резервную копию, пока плитки не использованы. Если плитка потеряется или публикация не удастся, ZIP восстановит набор без нового круга разделения. Удаляйте его только после того, как работа сделана.</p>\n<h2 id=\"step-8-name-and-organize\">Шаг 8. Назовите и организуйте</h2>\n<p>Скачанные плитки пронумерованы, но имена файлов общие. Переименуйте их, если задаче нужны осмысленные имена, например puzzle-row-1 или poster-tile-a1. Понятные имена предотвращают путаницу, когда в одной папке живут несколько разрезов.</p>\n<p>Держите каждый разрез в отдельной папке. Папка, названная по задаче, с плитками внутри по порядку, удобнее папки загрузок, полной пронумерованных файлов из разных проектов. Организация важнее всего, когда в сетке девять и более плиток.</p>\n<p>Для сеток Instagram держите плитки в порядке публикации, а не в порядке сетки. Платформа показывает сначала самый свежий пост, поэтому плитки нужно публиковать от последней позиции сетки к первой. Папка, отсортированная по порядку публикации, убирает догадки.</p>\n<p>Запишите настройки разреза где-нибудь, если будете повторять задачу. Сетку 3 на 3 из квадратного источника легко запомнить, а пользовательский разрез 4 на 5 с качеством JPG 85 — нет. Короткая заметка избавит вас от повторного поиска настроек в следующий раз.</p>\n<h2 id=\"step-9-check-the-tiles\">Шаг 9. Проверьте плитки</h2>\n<p>Откройте несколько плиток в полном размере и посмотрите на края. Каждая плитка должна показывать чистый разрез без полоски соседней плитки и без недостающей полосы вдоль границы. Чистый разрез невидим, когда плитки сидят вместе.</p>\n<p>Особенно проверьте первую и последнюю плитки. Крайние плитки выявляют проблемы с неравномерным делением, когда размеры изображения не разделились нацело и крайние плитки получились на пиксель-другой другими по размеру. Небольшая разница нормальна и редко видна.</p>\n<p>Посмотрите плитки вместе, если задача — сетка или пазл. Выложите их по порядку на экране или соберите в коллаж и убедитесь, что картинка восстанавливается правильно. Плитка не на месте очевидна, когда набор рассматривается как целое.</p>\n<p>Если плитка выглядит неправильно, не исправляйте её вручную. Вернитесь к разделителю, поправьте сетку или исходное изображение и разделите снова. Свежий разрез сохраняет все плитки согласованными, а плитка, отредактированная вручную, может отойти от остальных.</p>\n<h2 id=\"step-10-reuse-the-setup\">Шаг 10. Используйте настройки повторно</h2>\n<p>Сохраните настройки, которые сработали. Размер сетки, режим и формат плиток — это три числа, которые определяют разрез, и их повторное использование сохраняет серию разрезов последовательной. Еженедельный пазл сетки, построенный с теми же настройками, выглядит как серия, а не как набор случайностей.</p>\n<p>Разделите новое изображение с теми же настройками, загрузив его и применив те же числа. Инструмент ничего не запоминает между визитами, поэтому заметка, сделанная на шаге 8, — это и есть запись. Держите её вместе с файлами проекта.</p>\n<p>Когда форма источника меняется, настройки могут потребовать корректировки. Квадратный источник и широкий источник, разрезанные 3 на 3, дают плитки разной формы, поэтому проверяйте предпросмотр каждый раз, даже когда числа те же.</p>\n<p>Составьте в заметках небольшую библиотеку предустановок разреза: Instagram 3 на 3, постер 4 на 5, скриншот на 4 полосы и любой другой разрез, который вы используете часто. Письменный список превращает работу на пять минут в работу на одну минуту.</p>\n<h2 id=\"fixing-uneven-splits\">Как исправить неравномерные разрезы</h2>\n<p>Неравномерный разрез случается, когда размеры изображения не делятся нацело на строки или столбцы. Изображение 1000 пикселей, разрезанное на 3 столбца, даёт плитки 333, 333 и 334 пикселя, потому что лишние пиксели должны куда-то деться. Крайние плитки получаются на пиксель больше.</p>\n<p>Разница в один пиксель невидима почти при любом использовании. Посты в соцсетях, карусели и макеты печати переносят её без видимого шва. Не гонитесь за идеальным делением, когда разница на уровне пикселей не имеет видимого эффекта.</p>\n<p>Для пиксельно точной работы, например спрайт-листов, сначала обрежьте источник. Обрежьте изображение до размеров, которые делятся нацело на сетку, затем разделите. Лист 960 пикселей, разрезанный 3 на 3, даёт точные плитки по 320 пикселей без остатка.</p>\n<p>Проверьте размеры плиток в скачанном файле, если важна точность. Откройте плитки и подтвердите размеры, прежде чем использовать их в игровом движке или макете печати, где разница в один пиксель может сдвинуть выравнивание.</p>\n<h2 id=\"splitting-for-a-specific-platform\">Разделение под конкретную платформу</h2>\n<p>У каждой платформы свои ожидания от плиток. Сетки Instagram нуждаются в квадратных плитках, поэтому источник должен быть квадратным, а сетка — 3 на 3. Неквадратный источник даёт неквадратные плитки, которые ломают сетку профиля.</p>\n<p>Печати нужны плитки, соответствующие размеру бумаги. Постер, разрезанный для страниц А4, нуждается в плитках пропорций А4, поэтому задавайте сетку от размеров бумаги, а не от круглого числа. Число плиток следует из размера постера, делённого на размер страницы.</p>\n<p>Каруселям нужны плитки, которые читаются сами по себе. Панорама, разрезанная на вертикальные полосы, даёт полосы, каждая из которых показывает срез сцены, и каждый срез должен быть достаточно интересным, чтобы удержать свайп. Полоса, состоящая только из неба или пустой земли, тратит свайп впустую.</p>\n<p>Когда платформа меняет свой макет, разрез тоже может потребовать изменений. Instagram уже менял форму сетки профиля, и сетка, построенная под старую форму, может выглядеть неправильно на новой. Проверьте текущую сетку, прежде чем строить пазл.</p>\n<p>Для Telegram и VK разделитель тоже полезен. Длинный скриншот переписки, разрезанный на полосы, читается в чате гораздо лучше, чем одно огромное изображение, которое приходится увеличивать пальцами.</p>\n<p>Если вы разделяете скриншот с мелким текстом, проверьте читаемость каждой полосы отдельно. Полоса, которая в редакторе выглядит нормально, на экране телефона может оказаться слишком мелкой, и тогда стоит сделать полос больше.</p>\n<p>Для печати постера из плиток используйте плотную бумагу и обрезку по линейке. Тонкая бумага просвечивает, а неровная обрезка даёт видимые швы, которые испортят впечатление от собранного постера.</p>\n<p>Сохраняйте заметку с настройками разреза вместе с проектом. Через полгода вы не вспомните, была ли сетка 3 на 3 или 4 на 4, а заметка позволит повторить разрез за минуту.</p>\n<p>И не забывайте: исходник решает всё. Хороший разрез начинается не с инструмента, а с большого и резкого фото. Потратьте время на исходник — и плитки получатся сами.</p>\n<h2 id=\"quick-reference\">Краткая справка: чек-лист разреза</h2>\n<p>Загрузите большой источник, выберите режим «Сетка» или режим полос, задайте строки и столбцы или нажмите предустановку и проверьте пронумерованные линии разреза на лицах и тексте. Выберите JPG для фото и PNG для прозрачности.</p>\n<p>Скачайте ZIP-архив, держите плитки по порядку и публикуйте плитки сетки в обратном порядке. Если разрез лёг неудачно или плитки получились неравномерными, поправьте сетку или обрежьте источник и разделите снова.</p>\n<p>Полное руководство читайте в статье <a href=\"/ru/blog/razdelit-izobrazhenie-polnoe-rukovodstvo/\">Как разделить изображение: полное руководство</a>, а сетку Instagram подробно — в статье <a href=\"/ru/blog/razdelit-foto-dlya-setki-instagram/\">Как разделить фото для сетки Instagram</a>. Разделите изображение в <a href=\"/ru/razdelit-izobrazhenie/\">разделителе изображений</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Как узнать, сколько строк и столбцов выбрать?","answer":"Подбирайте число под задачу: 3 на 3 для сетки Instagram, 2 на 2 для простого разреза и столько полос, сколько у вас страниц или слайдов для длинного скриншота. Меньше плиток означает большие плитки, поэтому используйте наименьшее число, которое выполняет задачу."},{"question":"Что будет, если моё изображение не делится нацело?","answer":"Крайние плитки получаются на пиксель-другой больше остальных, потому что оставшиеся пиксели должны куда-то деться. Разница в один пиксель невидима при обычном использовании. Для пиксельно точной работы сначала обрежьте источник до размеров, которые делятся нацело."},{"question":"Можно ли разделить скриншот на страницы для печати?","answer":"Да. Используйте «Горизонтальные полосы» и задайте число полос, равное числу страниц, которые вы хотите получить. Каждая полоса печатается на своей странице, а полосы вместе содержат весь скриншот. Выбирайте число так, чтобы каждая полоса соответствовала размеру бумаги."},{"question":"Как собрать плитки обратно вместе?","answer":"Выложите их в пронумерованном порядке, слева направо и сверху вниз, начиная с плитки один в верхнем левом углу. Для сетки Instagram публикуйте их в обратном порядке, от последней плитки к первой, чтобы они встали на правильные позиции."},{"question":"Какой формат выбрать для плиток?","answer":"Выбирайте JPG для фотографий и для любого использования, где важны маленькие файлы, например для постов в соцсетях. Выбирайте PNG для графики, текста и прозрачных изображений, потому что PNG сохраняет каждый пиксель точно и сохраняет прозрачность."},{"question":"Можно ли разделить изображение на телефоне?","answer":"Да, разделитель работает в браузере и на телефонах, и на планшетах, и на компьютере. Загрузите из фотобиблиотеки, задайте сетку и скачайте ZIP-архив. Большой исходный файл работает лучше всего, поэтому используйте исходное фото, а не его сжатую копию."}];
